css_rules.declarations:
font-family: "Nunito Sans";
  font-weight: 400;
  font-style: normal;
  font-display: fallback;
  src: url("//zincsports.com/cdn/fonts/nunito_sans/nunitosans_n4.0276fe080df0ca4e6a22d9cb55aed3ed5ba6b1da.woff2") format("woff2"),
       url("//zincsports.com/cdn/fonts/nunito_sans/nunitosans_n4.b4964bee2f5e7fd9c3826447e73afe2baad607b7.woff") format("woff");

border: 0;
  background: transparent;
  display: block;
  height: 20px;
  width: 20px;
  min-width: 0;
  outline: none;
  line-height: 0px;
  font-size: 0px;
  color: transparent;
  padding: 0;
  cursor: pointer;
  position: relative;

position: absolute;
  pointer-events: auto;
  padding: 8px;
  background: #f2f2f2;
  color: #5c5c5c;
  border-radius: 0px;
  transition: all 50ms;

background: #f8d05b;
  border: 1.5px solid #f8d05b;
  color: #000000;
  font-size: 15px;
  line-height: 1em;
  height: auto;
  margin: 0;
  text-decoration: none !important;
  cursor: pointer;
  padding: 13px 31px 13px;
  text-align: center;
  border-radius: 0px;
  transition: background-color 100ms, color 100ms, border-color 100ms, opacity 100ms, transform 50ms;
  display: inline-block;
    font-family: "Nunito Sans", sans-serif;
    font-weight: 400;
    font-style: normal;
  -webkit-tap-highlight-color: transparent;

background: transparent;
  border: 0;
  color: inherit;
  font-size: inherit;
  line-height: inherit;
  padding: 0;
  vertical-align: baseline;
  border-radius: 0;
  display: inline;
  font-family: inherit;
  font-weight: inherit;
  font-style: inherit;

content: "";
  position: absolute;
  top: calc(50% - 0.5em);
  left: calc(50% - 0.5em);
  width: 1em;
  height: 1em;
  border-radius: 100%;
  border: 1px solid transparent;
  border-left-color: #5c5c5c;
  animation: loadingSpinner 1s linear infinite;

display: block;
  padding: 9px;
  color: #5c5c5c !important;
  background: #ffffff;
  border-radius: 0px;
  transition: all 100ms ease-out;

font-family: Jost, sans-serif;
    font-weight: 700;
    font-style: normal;
  color: #333333;
  line-height: 1.2;
  margin-bottom: 10px;
